&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Jeune seps&quot; href=&quot;#Jeune seps&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;div class=&quot;BDtitre&quot;&gt;Jeune Seps&lt;div style=&quot;float:right;&quot;&gt;FP 2&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Cr&#233;ature magique&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Cr&#233;ature magique.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;D&#233;sert&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/D&#233;sert.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Tropical&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Tropical.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 257&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt; 600 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Magique.html&quot; title=&quot;Cr&#233;ature magique&quot;&gt;Cr&#233;ature magique&lt;/a&gt; de taille M, N&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+5 ; &lt;b&gt;Sens &lt;/b&gt;vision dans le noir 18 m, vision nocturne, odorat ; Perception +9&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;16, contact 11, pris au d&#233;pourvu 15 (Dex +1, naturelle +5)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;22 (3d10+6)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+4, &lt;b&gt;Vig &lt;/b&gt;+5, &lt;b&gt;Vol &lt;/b&gt;+2&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;6 m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +4 (1d6-1 et poison)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; sang acide (2d6, DD 13 ; voir seps), poison&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For &lt;/b&gt;8, &lt;b&gt;Dex &lt;/b&gt;13, &lt;b&gt;Con &lt;/b&gt;14, &lt;b&gt;Int&lt;/b&gt; 1, &lt;b&gt;Sag &lt;/b&gt;13, &lt;b&gt;Cha &lt;/b&gt;6&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+3 ; &lt;b&gt;BMO &lt;/b&gt;+2 ; &lt;b&gt;DMD &lt;/b&gt;13 (croc-en-jambe impossible)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +10, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Perception, +4 en Discr&#233;tion&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;liqu&#233;faction (voir seps)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Poison (Ext)&lt;/b&gt;. Morsure – blessure ; JS Vigueur DD 13 ; fr&#233;quence 1/round pendant 10 rounds ; effet 1d4 acide et affaiblissement temporaire de 1d2 Con ; gu&#233;rison 2 JS cons&#233;cutifs.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de seps&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeune-Seps.html&quot; title=&quot;Seps, Jeune seps&quot;&gt;Jeune seps&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seps.html&quot; title=&quot;Seps&quot;&gt;Seps&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
&lt;i&gt;Ce serpent venimeux est prot&#233;g&#233; par une lourde carapace et poss&#232;de des crocs exceptionnellement grands.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les seps sont des serpents vivipares. Le petit atteint rapidement les 2,10 m&#232;tres de long pour un poids de 5 kilogrammes.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
